// panels wired to Karamba outputs + attach, solve, save
Grasshopper.Kernel.Special.GH_Panel Pan(string nick,float x,float y,params IGH_Param[] srcs){ var p=new Grasshopper.Kernel.Special.GH_Panel(); p.CreateAttributes(); p.NickName=nick; p.Attributes.Pivot=new System.Drawing.PointF(x,y); p.Attributes.Bounds=new System.Drawing.RectangleF(x,y,260,90); foreach(var s in srcs) p.AddSource(s); doc.AddObject(p,false); return p; }
float py=40; 
foreach(var k in keep){
 Pan(k.name+": mass [kg] | max disp [cm] | sum reactions [kN] | buckling factor",2200,py, k.asm.Params.Output.First(o=>o.Name.StartsWith("Mass")), k.an.Params.Output.First(o=>o.Name.StartsWith("Maximum")), k.rf.Params.Output.First(o=>o.Name.StartsWith("Sum of Reaction Forces")), k.buck.Params.Output.First(o=>o.Name.StartsWith("Buckling-load")));
 var gr=new Grasshopper.Kernel.Special.GH_Group(); gr.CreateAttributes(); gr.NickName=k.name+" (stage B) - ribs 150x250 C30/37, rigid joints, feet pinned, LC G = self-weight + 7 kN/m2 on the 167 m2 pyramid surface"; gr.Colour=System.Drawing.Color.FromArgb(70,200,220,255); foreach(var c in k.all) gr.AddObject(c.InstanceGuid); doc.AddObject(gr,false);
 py+=260; }
var note=new Grasshopper.Kernel.Special.GH_Panel(); note.CreateAttributes(); note.NickName="read me"; note.UserText="Karamba components copied from grasshopper/Pyramide Karamba 10_14_2026.gh (same cast C30/37 material, Trapezoid section, supports, Gravity, MeshLoad Const). Ribs 150x250 cm-inputs 25/15. Load case G = self-weight + 7 kN/m2 (ASSUMED casing/insulation/finish) applied by MeshLoad on the full 10x10 / 6.67 m pyramid surface (166.7 m2) -> distributed to nearest nodes. Geometry = PolyFrame stage B of friend-AP8-diagrid (left) and friend-16-diagrid (offset +14 m). Karamba geometry input unit must be mm (karamba.ini UnitLength). Stress check (|N|/A + |My|/Wy + |Mz|/Wz vs fcd 20 MPa / fctm 2.9 MPa) was done outside this file; see the report."; note.Attributes.Pivot=new System.Drawing.PointF(80,py+40); doc.AddObject(note,false); note.Attributes.Bounds=new System.Drawing.RectangleF(80,py+40,700,90);
var old=Instances.ActiveCanvas?.Document; Instances.DocumentServer.AddDocument(doc); Instances.ActiveCanvas.Document=doc; if(old!=null && old!=doc){ old.Enabled=false; Instances.DocumentServer.RemoveDocument(old); old.Dispose(); }
doc.Enabled=true; var sw=System.Diagnostics.Stopwatch.StartNew(); doc.NewSolution(false); 
foreach(var k in keep) Console.WriteLine(k.name+": mass "+string.Join(",",k.asm.Params.Output.First(o=>o.Name.StartsWith("Mass")).VolatileData.AllData(true))+" disp "+string.Join(",",k.an.Params.Output.First(o=>o.Name.StartsWith("Maximum")).VolatileData.AllData(true))+" buck "+string.Join(",",k.buck.Params.Output.First(o=>o.Name.StartsWith("Buckling-load")).VolatileData.AllData(true))+" sumR "+string.Join(",",k.rf.Params.Output.First(o=>o.Name.StartsWith("Sum of Reaction Forces")).VolatileData.AllData(true)));
Console.WriteLine("solve ms "+sw.ElapsedMilliseconds+" objs "+doc.ObjectCount);
var path="C:/Users/gonza/Documents/GitHub/pyramid-roof/polyframe2/friend-diagrid-karamba.gh";
if(System.IO.File.Exists(path)){ Console.WriteLine("EXISTS - not overwriting"); } else { var io3=new GH_DocumentIO(doc); Console.WriteLine("saved "+io3.SaveQuiet(path)); }
